msg.payload = ([
    { $match: { "_id": "init" } },
    { $project: { "outputs": 1, "_id": 0 } },
])

msg.topic = "load_all_mecanisms";

return msg;

var system = {
    device: msg.payload.device,
    entry: msg.payload.entry,
    payload: +msg.payload.active
}

if (msg.payload.system === "MCP") {
    return [system, null, null]
}

else if (msg.payload.system === "KMS") {
    return [null, system, null]
}

else if (msg.payload.system === "ESP") {
    return [null, null, system]
}

msg.payload = ([
    { $match: { "_id": "init" } },
    { $project: { "inputs": 1, "_id": 0 } },
])

msg.topic = "load_all_triggers";

return msg;

msg.triggers_list = msg.payload[0].inputs || []
msg.keypad = global.get('Memory.Keypad.Code');

if (global.get('Memory.Keypad.keypad_enabled') === true) {
    msg.keypad_enabled = true;
}
else {
    msg.keypad_enabled = false;
}

if (msg.keypad === "" || msg.keypad === undefined) {
    msg.keypad = "AUCUN CODE EN COURS";
}


return msg;

msg.payload = ([
    { $match: { "_id": "init" } }
])

msg.topic = "load_rooms_list";

return msg;

msg.payload = ([
    { $match: { "_id": "init" } }
])

msg.topic = "load_rooms_list";

return msg;

// LE RÉSULTAT DE L'AGRÉGATION ARRIVE SOUS FORME DE TABLEAU DANS MSG.PAYLOAD
var results = msg.payload || [];
var doc = results[0] || {};

// INITIALISATION SÉCURISÉE DE L'OBJET MCP23017 S'IL EST ABSENT
if (!doc.MCP23017) {
    doc.MCP23017 = {};
}

var usedMcp = doc.used_mcp || [];
var updateFields = {};

// =========================================================================
// 1. GÉNÉRATION DES ÉTATS ET MISE À JOUR CONCURRENTE (BASE & VARIABLE GLOBALE)
// =========================================================================
for (var i = 32; i < 40; i++) {
    var mcpName = "mcp" + i;
    // VÉRIFIE SI LE NOM DU MCP EST PRÉSENT DANS LE TABLEAU ÉPURÉ PAR MONGODB
    var isUsed = usedMcp.indexOf(mcpName) !== -1;

    // A. PRÉPARATION DE LA REQUÊTE POUR LA BASE DE DONNÉES
    updateFields["MCP23017." + mcpName + ".inuse"] = isUsed;

    // B. INITIALISATION DU SOUS-OBJET DANS LE DOCUMENT SI INEXISTANT
    if (!doc.MCP23017[mcpName]) {
        doc.MCP23017[mcpName] = {};
    }
    // C. MISE À JOUR EN DIRECT DE L'OBJET LOCAL POUR LA MÉMOIRE GLOBALE
    doc.MCP23017[mcpName].inuse = isUsed;
}

// =========================================================================
// 2. SAUVEGARDE EN MÉMOIRE GLOBALE DE L'OBJET MCP23017 DÉSORMAIS À JOUR
// =========================================================================
global.set("Memory.MCP", doc.MCP23017);

// =========================================================================
// 3. PRÉPARATION DES ARGUMENTS POUR LA MISE À JOUR GLOBALE UNIFIÉE MONGODB
// =========================================================================
var query = { "_id": "init" };
var update = { "$set": updateFields };
var options = { "upsert": true };

msg.operation = "updateOne";
msg.payload = [query, update, options];

delete msg.topic;
return msg;

// =========================================================================
// 1. REQUETE : PIPELINE D'AGRÉGATION OPTIMISÉ POUR FILTRER LES DONNÉES
// =========================================================================
var pipeline = [
    // ÉTAPE A : TROUVER LE DOCUMENT PAR SON ID UNIQUE
    { "$match": { "_id": "init" } },

    // ÉTAPE B : EXTRAIRE UNIQUEMENT L'OBJET MCP23017 À LA RACINE
    {
        "$replaceRoot": {
            "newRoot": { "$ifNull": ["$MCP23017", {}] }
        }
    }
];

var options = {};

// =========================================================================
// 2. ENCAPSULATION ET PARAMÉTRAGE POUR LE DRIVER MONGODB4 V3.4.0
// =========================================================================
msg.payload = [pipeline, options];
msg.operation = "aggregate";
msg.topic = "load_MCP_datas";

return msg;

// =========================================================================
// 1. INITIALISATION DE LA MÉMOIRE GLOBALE SI ABSENTE
// =========================================================================
var currentMemory = global.get("Memory.MCP") || {};
var updateFields = {};

// SÉCURISATION PRÉALABLE CONTRE LES PAQUETS MAL FORMÉS
if (!msg.payload) return null;

// =========================================================================
// 2. LOGIQUE DE FILTRAGE DES ENVOIS SELON LE TYPE DE MESSAGE RÉCEPTÉ
// =========================================================================
if (msg.payload.mcp === undefined) {
    // CAS A : MODIFICATION DE L'INTERRUPTEUR GÉNÉRAL
    updateFields["MCP23017.mcp_enabled"] = msg.payload.enabled;
    currentMemory.mcp_enabled = msg.payload.enabled;
} else {
    // CAS B : MODIFICATION D'UNE LIGNE SPÉCIFIQUE DE MCP (32 À 39)
    var key = msg.payload.mcp;

    // CIBLAGE ET MODIFICATION DES CLÉS INDIVIDUELLES EN BASE POUR PROTÉGER INUSE
    updateFields["MCP23017." + key + ".enabled"] = msg.payload.enabled;
    updateFields["MCP23017." + key + ".value_A"] = msg.payload.value_A;
    updateFields["MCP23017." + key + ".value_B"] = msg.payload.value_B;

    // SYNCHRONISATION DE L'OBJET EN MÉMOIRE GLOBALE SANS TOUCHER À INUSE
    if (!currentMemory[key]) {
        currentMemory[key] = {};
    }
    currentMemory[key].enabled = msg.payload.enabled;
    currentMemory[key].value_A = msg.payload.value_A;
    currentMemory[key].value_B = msg.payload.value_B;
}

// =========================================================================
// 3. ENREGISTREMENT EN VARIABLE GLOBALE ET PRÉPARATION MONGODB4 (1 SORTIE)
// =========================================================================
global.set("Memory.MCP", currentMemory);

var query = { "_id": "init" };
var update = { "$set": updateFields };
var options = { "upsert": true };

msg.operation = "updateOne";
msg.payload = [query, update, options];

delete msg.topic;
return msg;

// LE RÉSULTAT DE L'AGRÉGATION REÇU EN ENTRÉE CONTIENT LA LISTE DES KMS UTILISÉS
var results = msg.payload || [];
var doc = results[0] || {};
var usedKms = doc.used_kms || [];

// =========================================================================
// 1. CONFIGURATION DE L'OPÉRATION UPDATEONE VIA PIPELINE NATIF MONGODB 4
// =========================================================================
msg.operation = "updateOne";

// FILTRE DE RECHERCHE DU DOCUMENT UNIQUE
var query = { "_id": "init" };

// PIPELINE DE MISE À JOUR : APPLIQUE LA LOGIQUE SUR CHAQUE ÉLÉMENT DU TABLEAU EN BASE
var updatePipeline = [
    {
        "$set": {
            "KMS868.devices": {
                "$map": {
                    "input": { "$ifNull": ["$KMS868.devices", []] },
                    "as": "card",
                    "in": {
                        "$mergeObjects": [
                            "$$card",
                            {
                                "inuse": {
                                    "$in": ["$$card._id", usedKms]
                                }
                            }
                        ]
                    }
                }
            }
        }
    }
];

var options = { "upsert": true };

// ENCAPSULATION POUR LE DRIVER MONGODB4 V3.4.0
msg.payload = [query, updatePipeline, options];

delete msg.topic;
return msg;

// =========================================================================
// 1. REQUETE : PIPELINE D'AGRÉGATION OPTIMISÉ POUR L'AFFICHAGE DE L'IHM
// =========================================================================
var pipeline = [
    // ÉTAPE A : TROUVER LE DOCUMENT PAR SON ID UNIQUE 'INIT'
    { "$match": { "_id": "init" } },

    // ÉTAPE B : EXTRAIRE UNIQUEMENT L'OBJET KMS868 À LA RACINE DU MESSAGE
    {
        "$replaceRoot": {
            "newRoot": { "$ifNull": ["$KMS868", {}] }
        }
    }
];

var options = {};

// =========================================================================
// 2. ENCAPSULATION ET PARAMÉTRAGE POUR LE DRIVER MONGODB4 V3.4.0
// =========================================================================
msg.payload = [pipeline, options];
msg.operation = "aggregate";
msg.topic = "load_kms868s_list";

return msg;

// =========================================================================
// 1. REQUETE : PIPELINE D'AGRÉGATION OPTIMISÉ ET FILTRÉ POUR LES APPAREILS ESP
// =========================================================================
var pipeline = [
    // ÉTAPE A : TROUVER LE DOCUMENT PAR SON ID UNIQUE 'INIT'
    { "$match": { "_id": "init" } },

    // ÉTAPE B : FILTRER CHAQUE TABLEAU SUR SYSTEM:'ESP' ET N'EXTRAIRE QUE LES ID DE CARTE
    {
        "$project": {
            "used_esp": {
                "$setUnion": [
                    {
                        "$map": {
                            "input": {
                                "$filter": {
                                    "input": { "$ifNull": ["$inputs", []] },
                                    "as": "inp",
                                    "cond": { "$eq": ["$$inp.system", "ESP"] }
                                }
                            },
                            "as": "item_inp",
                            "in": "$$item_inp.device"
                        }
                    },
                    {
                        "$map": {
                            "input": {
                                "$filter": {
                                    "input": { "$ifNull": ["$outputs", []] },
                                    "as": "out",
                                    "cond": { "$eq": ["$$out.system", "ESP"] }
                                }
                            },
                            "as": "item_out",
                            "in": "$$item_out.device"
                        }
                    }
                ]
            }
        }
    },

    // ÉTAPE C : NETTOYER LA RACINE POUR NE CONSERVER QUE LA LISTE DES ESP UTILISÉS
    {
        "$replaceRoot": {
            "newRoot": {
                "used_esp": "$used_esp"
            }
        }
    }
];

var options = {};

// ENCAPSULATION STRICTE REQUISE POUR LE DRIVER MONGODB4 V3.4.0
msg.payload = [pipeline, options];
msg.operation = "aggregate";
msg.topic = "load_ESP_datas";

return msg;

// LE RÉSULTAT DE L'AGRÉGATION REÇU EN ENTRÉE CONTIENT LA LISTE DES ESP UTILISÉS
var results = msg.payload || [];
var doc = results[0] || {};
var usedEsp = doc.used_esp || [];

// =========================================================================
// 1. CONFIGURATION DE L'OPÉRATION UPDATEONE VIA PIPELINE NATIF MONGODB 4
// =========================================================================
msg.operation = "updateOne";

// FILTRE DE RECHERCHE DU DOCUMENT UNIQUE
var query = { "_id": "init" };

// PIPELINE DE MISE À JOUR : APPLIQUE LA LOGIQUE SUR CHAQUE ÉLÉMENT DU TABLEAU EN BASE
var updatePipeline = [
    {
        "$set": {
            "ESP32.devices": {
                "$map": {
                    "input": { "$ifNull": ["$ESP32.devices", []] },
                    "as": "card",
                    "in": {
                        "$mergeObjects": [
                            "$$card",
                            {
                                "inuse": {
                                    "$in": ["$$card._id", usedEsp]
                                }
                            }
                        ]
                    }
                }
            }
        }
    }
];

var options = { "upsert": true };

// ENCAPSULATION POUR LE DRIVER MONGODB4 V3.4.0
msg.payload = [query, updatePipeline, options];

delete msg.topic;
return msg;

// =========================================================================
// 1. REQUETE : PIPELINE D'AGRÉGATION OPTIMISÉ ET FILTRÉ POUR LES APPAREILS KMS
// =========================================================================
var pipeline = [
    // ÉTAPE A : TROUVER LE DOCUMENT PAR SON ID UNIQUE 'INIT'
    { "$match": { "_id": "init" } },

    // ÉTAPE B : FILTRER CHAQUE TABLEAU SUR SYSTEM:'KMS' ET N'EXTRAIRE QUE LES ID DE CARTE
    {
        "$project": {
            "used_kms": {
                "$setUnion": [
                    {
                        "$map": {
                            "input": {
                                "$filter": {
                                    "input": { "$ifNull": ["$inputs", []] },
                                    "as": "inp",
                                    "cond": { "$eq": ["$$inp.system", "KMS"] }
                                }
                            },
                            "as": "item_inp",
                            "in": "$$item_inp.device"
                        }
                    },
                    {
                        "$map": {
                            "input": {
                                "$filter": {
                                    "input": { "$ifNull": ["$outputs", []] },
                                    "as": "out",
                                    "cond": { "$eq": ["$$out.system", "KMS"] }
                                }
                            },
                            "as": "item_out",
                            "in": "$$item_out.device"
                        }
                    }
                ]
            }
        }
    },

    // ÉTAPE C : NETTOYER LA RACINE POUR NE CONSERVER QUE LA LISTE DES KMS UTILISÉS
    {
        "$replaceRoot": {
            "newRoot": {
                "used_kms": "$used_kms"
            }
        }
    }
];

var options = {};

// ENCAPSULATION STRICTE REQUISE POUR LE DRIVER MONGODB4 V3.4.0
msg.payload = [pipeline, options];
msg.operation = "aggregate";
msg.topic = "load_KMS_datas";

return msg;

// =========================================================================
// 1. REQUETE : PIPELINE D'AGRÉGATION OPTIMISÉ ET FILTRÉ POUR LES APPAREILS MCP
// =========================================================================
var pipeline = [
    // ÉTAPE A : TROUVER LE DOCUMENT PAR SON ID UNIQUE 'INIT'
    { "$match": { "_id": "init" } },

    // ÉTAPE B : FILTRER CHAQUE TABLEAU SUR SYSTEM:'MCP' ET N'EXTRAIRE QUE LES ID DE CARTE
    {
        "$project": {
            "used_mcp": {
                "$setUnion": [
                    {
                        "$map": {
                            "input": {
                                "$filter": {
                                    "input": { "$ifNull": ["$inputs", []] },
                                    "as": "inp",
                                    "cond": { "$eq": ["$$inp.system", "MCP"] }
                                }
                            },
                            "as": "item_inp",
                            "in": "$$item_inp.device"
                        }
                    },
                    {
                        "$map": {
                            "input": {
                                "$filter": {
                                    "input": { "$ifNull": ["$outputs", []] },
                                    "as": "out",
                                    "cond": { "$eq": ["$$out.system", "MCP"] }
                                }
                            },
                            "as": "item_out",
                            "in": "$$item_out.device"
                        }
                    }
                ]
            }
        }
    },

    // ÉTAPE C : NETTOYER LA RACINE POUR NE CONSERVER QUE LA LISTE DES MCP UTILISÉS
    {
        "$replaceRoot": {
            "newRoot": {
                "used_mcp": "$used_mcp"
            }
        }
    }
];

var options = {};

// ENCAPSULATION STRICTE POUR NODE-RED-CONTRIB-MONGODB4 V3.4.0
msg.payload = [pipeline, options];
msg.operation = "aggregate";
msg.topic = "load_MCP_datas";

return msg;

// =========================================================================
// 1. REQUETE : PIPELINE D'AGRÉGATION OPTIMISÉ POUR L'DISPLAY DE L'IHM ESP32
// =========================================================================
var pipeline = [
    // ÉTAPE A : TROUVER LE DOCUMENT PAR SON ID UNIQUE 'INIT'
    { "$match": { "_id": "init" } },

    // ÉTAPE B : EXTRAIRE UNIQUEMENT L'OBJET ESP32 À LA RACINE DU MESSAGE
    {
        "$replaceRoot": {
            "newRoot": { "$ifNull": ["$ESP32", {}] }
        }
    }
];

var options = {};

// =========================================================================
// 2. ENCAPSULATION ET PARAMÉTRAGE POUR LE DRIVER MONGODB4 V3.4.0
// =========================================================================
msg.payload = [pipeline, options];
msg.operation = "aggregate";
msg.topic = "load_esp32s_list";

return msg;

// SÉCURISATION PRÉALABLE CONTRE LES PAQUETS VIDES OU MAL FORMÉS
if (!msg || !msg.topic) return null;

// =========================================================================
// 1. CAS RELOAD_KMS868 : LE SIGNAL COURT-CIRCUITE LA BASE ET SORT SUR LA SORTIE 2
// =========================================================================
if (msg.topic === "reload_kms868") {
    var msgDirectRefresh = { "topic": "load_kms868s_list", "payload": {} };
    return [null, msgDirectRefresh];
}

// =========================================================================
// 2. CAS SAVE_KMS868 : ROUTAGE UNIQUE UNIFIÉ ET ADAPTATION CHIRURGICALE
// =========================================================================
if (msg.topic === "save_kms868") {
    var data = msg.payload || {};
    var queryKms = {};
    var saveKms = {};

    // centralisation et factorisation des champs pour eviter la duplication de code
    var kmsObj = {
        "name": data.name || "",
        "device": data.device || ""
    };

    // si la platine kms est nouvelle (injection de l'id msg._msgid via push)
    if (data._id === "new") {
        queryKms = { "_id": "init" };
        saveKms = {
            "$push": {
                "KMS868.devices": Object.assign({ "_id": msg._msgid }, kmsObj)
            }
        };
    }
    // si la platine kms existe deja (filtrage de l'id et mise a jour globale via set positionnel)
    else {
        queryKms = {
            "_id": "init",
            "KMS868.devices._id": data._id
        };
        saveKms = {
            "$set": {
                "KMS868.devices.$": Object.assign({ "_id": data._id }, kmsObj)
            }
        };
    }

    // formatage strict [query, update, options] pour le driver mongodb4
    msg.payload = [queryKms, saveKms, { "upsert": false }];
    msg.operation = "updateOne";
    return [msg, null];
}

// =========================================================================
// 3. CAS DELETE_KMS868 : PURGE DE LA RAM ET SUPPRESSION EN BASE DE DONNÉES
// =========================================================================
if (msg.topic === "delete_kms868") {
    // sécurité matérielle : purge nette de la variable globale en ram avant la suppression
    if (msg.payload && msg.payload.device) {
        global.set("Memory.KMS868." + msg.payload.device, undefined);
    }

    var queryDel = { "_id": "init" };
    var updateDel = {
        "$pull": {
            "KMS868.devices": {
                "_id": msg.payload._id
            }
        }
    };

    msg.payload = [queryDel, updateDel, { "upsert": false }];
    msg.operation = "updateOne";
    return [msg, null];
}

// =========================================================================
// 4. CAS ENABLED_KMS_CONFIG : ACTIVATION CHIRURGICALE DU COMMUTATEUR GENERAL
// =========================================================================
if (msg.topic === "enabled_kms_config") {
    var queryEnable = { "_id": "init" };
    var updateEnable = {
        "$set": {
            "KMS868.kms_enabled": msg.payload.enabled
        }
    };

    msg.payload = [queryEnable, updateEnable, { "upsert": false }];
    msg.operation = "updateOne";
    return [msg, null];
}

return null;

// SÉCURISATION PRÉALABLE CONTRE LES PAQUETS VIDES OU MAL FORMÉS
if (!msg || !msg.topic) return null;

// =========================================================================
// 1. CAS RELOAD_ESP32 : LE SIGNAL COURT-CIRCUITE LA BASE ET SORT SUR LA SORTIE 2
// =========================================================================
if (msg.topic === "reload_esp32") {
    var msgDirectRefresh = { "topic": "load_esp32s_list", "payload": {} };
    return [null, msgDirectRefresh];
}

// =========================================================================
// 2. CAS SAVE_ESP32 : ROUTAGE UNIQUE UNIFIÉ ET ADAPTATION CHIRURGICALE
// =========================================================================
if (msg.topic === "save_esp32") {
    var data = msg.payload || {};
    var queryEsp = {};
    var saveEsp = {};

    // centralisation et factorisation des champs pour eviter la duplication de code
    var espObj = {
        "device": data.device || "",
        "number_input": data.number_input || "0",
        "number_output": data.number_output || "0",
        "number_rfid": data.number_rfid || "0"
    };

    // si le module esp32 est nouveau (injection de l'id msg._msgid via push)
    if (data._id === "new") {
        queryEsp = { "_id": "init" };
        saveEsp = {
            "$push": {
                "ESP32.devices": Object.assign({ "_id": msg._msgid }, espObj)
            }
        };
    }
    // si le module esp32 existe deja (filtrage de l'id et mise a jour globale via set positionnel)
    else {
        queryEsp = {
            "_id": "init",
            "ESP32.devices._id": data._id
        };
        saveEsp = {
            "$set": {
                "ESP32.devices.$": Object.assign({ "_id": data._id }, espObj)
            }
        };
    }

    // formatage strict [query, update, options] pour le driver mongodb4
    msg.payload = [queryEsp, saveEsp, { "upsert": false }];
    msg.operation = "updateOne";
    return [msg, null];
}

// =========================================================================
// 3. CAS DELETE_ESP32 : PURGE DE LA RAM ET SUPPRESSION EN BASE DE DONNÉES
// =========================================================================
if (msg.topic === "delete_esp32") {
    // sécurité matérielle : purge nette de la variable globale en ram avant la suppression
    if (msg.payload && msg.payload.device) {
        global.set("Memory.ESP32." + msg.payload.device, undefined);
    }

    var queryDel = { "_id": "init" };
    var updateDel = {
        "$pull": {
            "ESP32.devices": {
                "_id": msg.payload._id
            }
        }
    };

    msg.payload = [queryDel, updateDel, { "upsert": false }];
    msg.operation = "updateOne";
    return [msg, null];
}

// =========================================================================
// 4. CAS ENABLED_ESP_CONFIG : ACTIVATION CHIRURGICALE DU COMMUTATEUR GENERAL
// =========================================================================
if (msg.topic === "enabled_esp_config") {
    var queryEnable = { "_id": "init" };
    var updateEnable = {
        "$set": {
            "ESP32.esp_enabled": msg.payload.enabled
        }
    };

    msg.payload = [queryEnable, updateEnable, { "upsert": false }];
    msg.operation = "updateOne";
    return [msg, null];
}

return null;

// =========================================================================
// 1. REQUETE : PIPELINE D'AGRÉGATION OPTIMISÉ POUR L'AFFICHAGE DE L'IHM KEYPAD
// =========================================================================
var pipeline = [
    // ÉTAPE A : TROUVER LE DOCUMENT PAR SON ID UNIQUE 'INIT'
    { "$match": { "_id": "init" } },

    // ÉTAPE B : EXTRARE UNIQUEMENT L'OBJET KEYPAD À LA RACINE DU MESSAGE
    {
        "$replaceRoot": {
            "newRoot": { "$ifNull": ["$KEYPAD", {}] }
        }
    }
];

var options = {};

// =========================================================================
// 2. ENCAPSULATION ET PARAMÉTRAGE POUR LE DRIVER MONGODB4 V3.4.0
// =========================================================================
msg.payload = [pipeline, options];
msg.operation = "aggregate";
msg.topic = "load_keypad_list";

return msg;

// SÉCURISATION PRÉALABLE CONTRE LES PAQUETS VIDES OU MAL FORMÉS
if (!msg || !msg.topic) return null;

// =========================================================================
// 1. CAS ENABLED_KEYPAD_CONFIG : ENREGISTREMENT ET VERROUILLAGE RAM PERSISTANTE
// =========================================================================
if (msg.topic === "enabled_keypad_config") {
    // REPRISE STRICTE DE VOTRE MISE À JOUR DE VARIABLE GLOBALE MEMORY
    global.set("Memory.Keypad.keypad_enabled", msg.payload.enabled);

    var query = { "_id": "init" };
    var updateDoc = {
        "$set": {
            "KEYPAD.Keypad_Enabled": msg.payload.enabled
        }
    };

    msg.payload = [query, updateDoc, { "upsert": false }];
    msg.operation = "updateOne";
    return [msg, null];
}

return null;

// =========================================================================
// 1. REQUETE : PIPELINE D'AGRÉGATION OPTIMISÉ POUR L'AFFICHAGE DE L'IHM SPEAKERS
// =========================================================================
var pipeline = [
    // ÉTAPE A : TROUVER LE DOCUMENT PAR SON ID UNIQUE 'INIT'
    { "$match": { "_id": "init" } },

    // ÉTAPE B : EXTRAIRE UNIQUEMENT L'OBJET SPEAKERS À LA RACINE DU MESSAGE
    {
        "$replaceRoot": {
            "newRoot": { "$ifNull": ["$SPEAKERS", {}] }
        }
    }
];

var options = {};

// =========================================================================
// 2. ENCAPSULATION ET PARAMÉTRAGE POUR LE DRIVER MONGODB4 V3.4.0
// =========================================================================
msg.payload = [pipeline, options];
msg.operation = "aggregate";
msg.topic = "load_speakers_list";

return msg;

// SECURISATION PRÉALABLE CONTRE LES PAQUETS VIDES OU MAL FORMÉS
if (!msg || !msg.topic) return null;

// =========================================================================
// 1. CAS CHANGE_SPEAKERS_COUNT : ENREGISTREMENT ET VERROUILLAGE RAM PERSISTANTE
// =========================================================================
if (msg.topic === "change_speakers_count") {
    // REPRISE STRICTE DE LA MISE À JOUR DE VARIABLE GLOBALE MEMORY
    global.set("Memory.Speaker.number_of_speakers", msg.payload.number_of_speakers);

    var query = { "_id": "init" };
    var updateDoc = {
        "$set": {
            "SPEAKERS.NumberOfSpeakers": +msg.payload.number_of_speakers
        }
    };

    msg.payload = [query, updateDoc, { "upsert": false }];
    msg.operation = "updateOne";
    return [msg, null];
}

return null;

// =========================================================================
// 1. REQUETE : PIPELINE D'AGRÉGATION OPTIMISÉ POUR L'AFFICHAGE DE L'IHM SCREENS
// =========================================================================
var pipeline = [
    // ÉTAPE A : TROUVER LE DOCUMENT PAR SON ID UNIQUE 'INIT'
    { "$match": { "_id": "init" } },

    // ÉTAPE B : EXTRAIRE UNIQUEMENT L'OBJET SCREENS À LA RACINE DU DOCUMENT
    {
        "$replaceRoot": {
            "newRoot": { "$ifNull": ["$SCREENS", {}] }
        }
    }
];

var options = {};

// =========================================================================
// 2. ENCAPSULATION ET PARAMÉTRAGE POUR LE DRIVER MONGODB4 V3.4.0
// =========================================================================
msg.payload = [pipeline, options];
msg.operation = "aggregate";
msg.topic = "load_screens_list";

return msg;

// SÉCURISATION PRÉALABLE CONTRE LES PAQUETS VIDES OU MAL FORMÉS
if (!msg || !msg.topic) return null;

// =========================================================================
// 1. CAS RELOAD_SCREEN : LE SIGNAL COURT-CIRCUITE LA BASE ET SORT SUR LA SORTIE 2
// =========================================================================
if (msg.topic === "reload_screen") {
    var msgDirectRefresh = { "topic": "load_screens_list", "payload": {} };
    return [null, msgDirectRefresh];
}

// =========================================================================
// 2. CAS SAVE_SCREEN : ROUTAGE UNIQUE UNIFIÉ ET ADAPTATION CHIRURGICALE
// =========================================================================
if (msg.topic === "save_screen") {
    var data = msg.payload || {};
    var queryScreen = {};
    var saveScreen = {};

    // centralisation et factorisation des champs pour eviter la duplication de code
    var screenObj = {
        "device_name": data.device_name || "",
        "device": data.device || "",
        "screen": data.screen || "screen_1"
    };

    // si l'ecran est nouveau (injection de l'id msg._msgid via push)
    if (data._id === "new") {
        queryScreen = { "_id": "init" };
        saveScreen = {
            "$push": {
                "SCREENS.devices": Object.assign({ "_id": msg._msgid }, screenObj)
            }
        };
    }
    // si l'ecran existe deja (filtrage de l'id et mise a jour globale via set positionnel)
    else {
        queryScreen = {
            "_id": "init",
            "SCREENS.devices._id": data._id
        };
        saveScreen = {
            "$set": {
                "SCREENS.devices.$": Object.assign({ "_id": data._id }, screenObj)
            }
        };
    }

    // formatage strict [query, update, options] pour le driver mongodb4
    msg.payload = [queryScreen, saveScreen, { "upsert": false }];
    msg.operation = "updateOne";
    return [msg, null];
}

// =========================================================================
// 3. CAS DELETE_SCREEN : PURGE DE LA RAM ET SUPPRESSION EN BASE DE DONNÉES
// =========================================================================
if (msg.topic === "delete_screen") {
    // sécurité matérielle : purge nette de la variable globale avant la suppression en base
    if (msg.payload && msg.payload.device) {
        global.set("Memory.Screen." + msg.payload.device, undefined);
    }

    var queryDel = { "_id": "init" };
    var updateDel = {
        "$pull": {
            "SCREENS.devices": {
                "_id": msg.payload._id
            }
        }
    };

    msg.payload = [queryDel, updateDel, { "upsert": false }];
    msg.operation = "updateOne";
    return [msg, null];
}

return null;
